#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAXN 10

static int parent[MAXN];
static int rank_arr[MAXN];

static int find_set(int v) {
    if (parent[v] != v)
        parent[v] = find_set(parent[v]);
    return parent[v];
}

static void union_sets(int a, int b) {
    a = find_set(a);
    b = find_set(b);
    if (a != b) {
        if (rank_arr[a] < rank_arr[b])
            parent[a] = b;
        else if (rank_arr[a] > rank_arr[b])
            parent[b] = a;
        else {
            parent[b] = a;
            rank_arr[a]++;
        }
    }
}

int main(int argc, char *argv[]) {
    // initialize union‑find for elements 0..9
    for (int i = 0; i < MAXN; ++i) {
        parent[i] = i;
        rank_arr[i] = 0;
    }

    if (argc < 2) {
        puts("NOOP");
        return 0;
    }

    int i = 1; // start after program name
    while (i < argc) {
        char *cmd = argv[i];
        if (strcmp(cmd, "U") == 0) { // UNION a b
            if (i + 2 >= argc) {
                puts("INVALID");
                i += 3; // skip past what would be the arguments
                continue;
            }
            long a = strtol(argv[i + 1], NULL, 10);
            long b = strtol(argv[i + 2], NULL, 10);
            if (a < 0 || a >= MAXN || b < 0 || b >= MAXN) {
                puts("INVALID");
            } else {
                union_sets((int)a, (int)b);
                printf("UNION %ld %ld\n", a, b);
            }
            i += 3;
        } else if (strcmp(cmd, "F") == 0) { // FIND a
            if (i + 1 >= argc) {
                puts("INVALID");
                i += 2;
                continue;
            }
            long a = strtol(argv[i + 1], NULL, 10);
            if (a < 0 || a >= MAXN) {
                puts("INVALID");
            } else {
                int root = find_set((int)a);
                printf("FIND %ld=%d\n", a, root);
            }
            i += 2;
        } else if (strcmp(cmd, "C") == 0) { // CONNECTED a b
            if (i + 2 >= argc) {
                puts("INVALID");
                i += 3;
                continue;
            }
            long a = strtol(argv[i + 1], NULL, 10);
            long b = strtol(argv[i + 2], NULL, 10);
            if (a < 0 || a >= MAXN || b < 0 || b >= MAXN) {
                puts("INVALID");
            } else {
                if (find_set((int)a) == find_set((int)b))
                    puts("YES");
                else
                    puts("NO");
            }
            i += 3;
        } else {
            // unknown token – treat as invalid and move on
            puts("INVALID");
            ++i;
        }
    }
    return 0;
}
